schema.example:
type Query { order(id: ID!, status: Status): Order }
type Mutation { setStatus(input: OrderInput!): Order! }

enum Status { OPEN CLOSED }
input OrderInput { status: Status! note: String }

type Order {
  id: ID!
  status: Status!
  deprecatedRef: String! @deprecated(reason: "use id")
  note: String
}
